import type { BriefRecord, BriefRefusal } from "@amykit/core";

/** The sections a feature's brief answers, in the order grooming asks them. */
export const BRIEF_SECTIONS = ["Goal", "Sources", "Criteria", "Out of scope"] as const;

function lines(brief: Pick<BriefRecord, "sections">, name: string): string[] {
  return (brief.sections.find((section) => section.name === name)?.body ?? "")
    .split("\n")
    .map((line) => line.trim().replace(/^- /, ""))
    .filter((line) => line !== "");
}

/**
 * Judges a groomed brief: every source is `S<n>: where it comes from`, and
 * every criterion is `C<n>: what holds (source: S<n>)`, citing a source the
 * brief lists. A criterion naming no source is a requirement nobody can
 * trace, and the proof would be asked to show it anyway.
 */
export function checkBrief(brief: Pick<BriefRecord, "sections">): BriefRefusal[] {
  const refusals: BriefRefusal[] = [];
  const sources = new Set<string>();
  for (const line of lines(brief, "Sources")) {
    const id = /^(S\d+): \S/.exec(line)?.[1];
    if (id === undefined) refusals.push({ section: "Sources", rule: `\`${line}\` is not \`S<n>: where it comes from\`` });
    else sources.add(id);
  }
  const criteria = new Set<string>();
  for (const line of lines(brief, "Criteria")) {
    const read = /^(C\d+): .+ \(source: (S\d+)\)$/.exec(line);
    if (!read) {
      refusals.push({ section: "Criteria", rule: `\`${line}\` is not \`C<n>: what holds (source: S<n>)\`` });
      continue;
    }
    if (criteria.has(read[1]!)) refusals.push({ section: "Criteria", rule: `${read[1]} is named twice` });
    criteria.add(read[1]!);
    if (!sources.has(read[2]!)) refusals.push({ section: "Criteria", rule: `${read[1]} cites ${read[2]}, which Sources does not list` });
  }
  return refusals;
}

/** The criteria a brief settled, by id, in the order it lists them. */
export function criteriaOf(brief: Pick<BriefRecord, "sections">): string[] {
  return lines(brief, "Criteria").flatMap((line) => /^(C\d+): /.exec(line)?.[1] ?? []);
}

import type { BaseSource, BaseSourceSnapshot, BriefStore, Feature, GroomedWork, GroomingTracker } from "@amykit/core";

export const GROOMING_WORKFLOW = "feature-grooming";

/** A proposed item and the source files that made it necessary. */
export interface ProposedWork {
  key: string;
  title: string;
  body: string;
}

/** Policy is deliberately owned by the workflow rather than parsed by core. */
export interface Groomer {
  propose(feature: Feature, sources: readonly BaseSourceSnapshot[]): Promise<readonly ProposedWork[]>;
}

export interface GroomingResult {
  featureId: string;
  created: string[];
  revised: string[];
  retired: string[];
}

/**
 * Reconciles a feature's generated work from fresh base-branch snapshots.
 *
 * The source capability is intentionally narrow. This function receives no
 * Git, branch, commit, checkout path, or worktree; the only source operation
 * it can perform is read through BaseSource.snapshot(). Provenance is kept on
 * tracker work (`groomedBy`), never overloaded onto Brief.explains.
 */
export async function groomFeature(
  feature: Feature,
  deps: { source: BaseSource; tracker: GroomingTracker; briefs: BriefStore; groomer: Groomer; now: () => Date },
): Promise<GroomingResult> {
  const snapshots = await Promise.all(feature.repos.map((repo) => deps.source.snapshot(repo)));
  const proposals = await deps.groomer.propose(feature, snapshots);
  const existing = await deps.tracker.groomedWork(feature.id, GROOMING_WORKFLOW);
  const byKey = new Map(existing.filter((work) => !work.retired).map((work) => [workKey(work), work]));
  const wanted = new Set(proposals.map((proposal) => proposal.key));
  const result: GroomingResult = { featureId: feature.id, created: [], revised: [], retired: [] };

  for (const proposal of proposals) {
    const current = byKey.get(proposal.key);
    const body = withKey(proposal);
    if (!current) {
      const created = await deps.tracker.createGroomedWork({
        featureId: feature.id,
        groomedBy: GROOMING_WORKFLOW,
        title: proposal.title,
        body,
      });
      result.created.push(created.id);
    } else if (current.title !== proposal.title || current.body !== body) {
      await deps.tracker.updateGroomedWork(current.id, { title: proposal.title, body });
      result.revised.push(current.id);
    }
  }

  for (const work of existing) {
    if (!work.retired && !wanted.has(workKey(work))) {
      await deps.tracker.retireGroomedWork(work.id);
      result.retired.push(work.id);
    }
  }

  // `write` replaces membership and increments the revision while the store
  // preserves its independent question log. Membership is only grooming-owned
  // work: a human's feature ticket is never adopted just because it shares an id.
  const current = await deps.tracker.groomedWork(feature.id, GROOMING_WORKFLOW);
  await deps.briefs.write({
    id: feature.id,
    sections: [{ name: feature.title, body: feature.body ?? "" }],
    explains: current.filter((work) => !work.retired).map((work) => work.id),
    at: deps.now().toISOString(),
  });
  return result;
}

function withKey(proposal: ProposedWork): string {
  return `<!-- amy:grooming-key=${proposal.key} -->\n${proposal.body}`;
}

function workKey(work: GroomedWork): string {
  return /<!-- amy:grooming-key=([^ ]+) -->/.exec(work.body)?.[1] ?? work.id;
}

export { plugin, configSchema } from "./plugin.js";
export type { GroomingRecord } from "./plugin.js";
export { BRIEF_SECTIONS, checkBrief, criteriaOf } from "./brief.js";
export { GROOMING_WORKFLOW, groomFeature } from "./groom.js";
export type { Groomer, GroomingResult, ProposedWork } from "./groom.js";

import { BRANCH_SETTINGS, BriefStore, ConfigSchema, WorkRecord, advance, defineWorkflow, port, wait } from "@amykit/core";
import { BRIEF_SECTIONS, checkBrief, criteriaOf } from "./brief.js";

export const configSchema = {
  repos: { type: "string[]", required: true, description: "repositories whose configured base branch grooming may read" },
  ...BRANCH_SETTINGS,
  "policy.briefLookMs": { type: "number", default: 5 * 60 * 1000, description: "how often a brief still being groomed is looked at again" },
} satisfies ConfigSchema;

/** The feature a brief explains, and what it settled once it is groomed. */
export interface GroomingRecord extends WorkRecord {
  state: "GROOMING" | "BRIEFED";
  criteria?: string[];
}

interface Observation {
  readonly unit: string;
  readonly refusals: readonly string[];
  readonly criteria: readonly string[];
}

/** The feature a record grooms: the work it was called for, the brief's id. */
function unitOf(record: { readonly id: string }): string {
  return record.id.split("/")[0]!;
}

/**
 * A feature, groomed into a brief a project's other phases can trust.
 *
 * The brief is written through the brief port by whoever grooms it — a
 * person with `amy-groom` — and this walk waits, as a look, until the brief
 * answers every section it declares and its check accepts it. It then
 * returns the criteria the brief settled: what the work is for and what the
 * proof is asked to show.
 *
 * It mounts no port of its own, so a project's `brief/` can call it: a
 * workflow that registers ports is mounted, never called. Reading the base
 * branch is `amy-groom`'s, and reconciling a tracker's groomed work is
 * `groomFeature`, handed the source and tracker its caller has.
 */
export const plugin = defineWorkflow({
  name: "feature-grooming",
  pluginName: "@amykit/workflow-feature-grooming",
  configSchema,
  policy: { briefLookMs: configSchema["policy.briefLookMs"].default },
  needs: { brief: port<BriefStore>() },
  brief: { sections: [...BRIEF_SECTIONS], check: (record) => checkBrief(record) },
  output: { BRIEFED: (record: GroomingRecord) => ({ criteria: record.criteria ?? [] }) },
  record: () => ({}),
  discover: async () => [],
  async observe(scope, record): Promise<Observation> {
    const unit = unitOf(record);
    const brief = await scope.ports.brief.get(unit);
    if (!brief) return { unit, refusals: ["there is no brief yet"], criteria: [] };
    const blank = BRIEF_SECTIONS.filter((name) => (brief.sections.find((section) => section.name === name)?.body ?? "").trim() === "");
    const refusals = blank.length > 0
      ? blank.map((name) => `${name} is not answered`)
      : checkBrief(brief).map((refusal) => `${refusal.section}: ${refusal.rule}`);
    return { unit, refusals, criteria: criteriaOf(brief) };
  },
  actions: {},
  remember: (_scope, record: GroomingRecord, _outcomes, observation: Observation) =>
    record.state === "BRIEFED" && record.criteria === undefined ? { ...record, criteria: [...observation.criteria] } : record,
  decide: {
    GROOMING: (_record: GroomingRecord, observation: Observation, policy: { briefLookMs: number }) => observation.refusals.length === 0
      ? advance("BRIEFED", `the brief of ${observation.unit} settles ${observation.criteria.length} criteria`)
      : wait(policy.briefLookMs, `the brief of ${observation.unit} is still being groomed: ${observation.refusals.join("; ")}`),
    BRIEFED: () => ({ kind: "settled", why: "the brief is groomed, and what it settled was returned" }),
  },
});
